(async () => {
    await ensureHeroEmployeeProfileColumns();
    await ensureHeroSiteLocationColumns();
    await ensureEmergencyIncidentColumns();
    await ensureTrainingRecordHistoryColumns();
    await ensureApprovalBlueprintSeedData();
